package collector

import("context";"encoding/json";"errors";"io";"log/slog";"sync";"testing";"time";"github.com/shubhendu-abhishek/gpu-telemetry-pipeline/internal/queue";"github.com/shubhendu-abhishek/gpu-telemetry-pipeline/internal/telemetry")
type fakeQueue struct{mu sync.Mutex;messages []queue.Message;acked,nacked,claims int;claimErr,ackErr,nackErr error;afterClaim func()}
func(q *fakeQueue)Claim(_ context.Context,_ string,_ int,_ time.Duration)([]queue.Message,error){q.mu.Lock();q.claims++;if q.claimErr!=nil{err:=q.claimErr;q.mu.Unlock();return nil,err};out:=q.messages;q.messages=nil;hook:=q.afterClaim;q.mu.Unlock();if hook!=nil{hook()};return out,nil}
func(q *fakeQueue)Ack(context.Context,string,string)error{q.mu.Lock();defer q.mu.Unlock();q.acked++;return q.ackErr}
func(q *fakeQueue)Nack(context.Context,string,string,time.Duration,int,string)error{q.mu.Lock();defer q.mu.Unlock();q.nacked++;return q.nackErr}
type fakeSink struct{err error;saved int}
func(s *fakeSink)SaveTelemetry(context.Context,string,telemetry.Record)error{s.saved++;return s.err}
func testRecord()telemetry.Record{return telemetry.Record{StreamedAt:time.Now().UTC(),SourceTimestamp:time.Now().UTC(),GPUUUID:"GPU-1",MetricName:"GPU_UTIL"}}
func TestProcessAcksPersistedMessage(t *testing.T){payload,_:=json.Marshal(testRecord());q:=&fakeQueue{};sink:=&fakeSink{};c:=&Collector{Queue:q,Sink:sink,Config:Config{MaxAttempts:3},Logger:slog.New(slog.NewTextHandler(io.Discard,nil))};c.process(context.Background(),"worker",queue.Message{ID:"m1",Payload:payload,Attempts:1});if sink.saved!=1||q.acked!=1||q.nacked!=0{t.Fatalf("saved=%d ack=%d nack=%d",sink.saved,q.acked,q.nacked)}}
func TestProcessNacksStorageFailure(t *testing.T){payload,_:=json.Marshal(testRecord());q:=&fakeQueue{};sink:=&fakeSink{err:errors.New("database down")};c:=&Collector{Queue:q,Sink:sink,Config:Config{MaxAttempts:3},Logger:slog.New(slog.NewTextHandler(io.Discard,nil))};c.process(context.Background(),"worker",queue.Message{ID:"m1",Payload:payload,Attempts:1});if q.nacked!=1||q.acked!=0{t.Fatalf("ack=%d nack=%d",q.acked,q.nacked)}}
func TestProcessNacksInvalidPayload(t *testing.T){q:=&fakeQueue{};c:=&Collector{Queue:q,Sink:&fakeSink{},Config:Config{MaxAttempts:3}};c.process(context.Background(),"worker",queue.Message{ID:"m1",Payload:[]byte("not-json"),Attempts:1});if q.nacked!=1{t.Fatalf("expected nack, got %d",q.nacked)}}
func TestRunRejectsInvalidConfig(t *testing.T){c:=&Collector{Queue:&fakeQueue{},Sink:&fakeSink{},ID:"x",Config:Config{Workers:11,BatchSize:1,PollInterval:time.Second,LeaseDuration:time.Second,MaxAttempts:1}};if err:=c.Run(context.Background());err==nil{t.Fatal("expected configuration error")}}
func TestRunStopsAfterCancellation(t *testing.T){ctx,cancel:=context.WithCancel(context.Background());q:=&fakeQueue{};c:=&Collector{Queue:q,Sink:&fakeSink{},ID:"x",Config:Config{Workers:1,BatchSize:1,PollInterval:time.Millisecond,LeaseDuration:time.Second,MaxAttempts:3}};done:=make(chan error,1);go func(){done<-c.Run(ctx)}();time.Sleep(5*time.Millisecond);cancel();select{case err:=<-done:if err!=nil{t.Fatal(err)};case<-time.After(time.Second):t.Fatal("collector did not stop")}}
func TestProcessRejectsMissingRequiredFields(t *testing.T){payload,_:=json.Marshal(telemetry.Record{ProcessedAt:time.Now().UTC(),MetricName:"UTIL"});q:=&fakeQueue{};sink:=&fakeSink{};c:=&Collector{Queue:q,Sink:sink,Config:Config{MaxAttempts:3}};c.process(context.Background(),"worker",queue.Message{ID:"bad",Payload:payload,Attempts:1});if q.nacked!=1||sink.saved!=0{t.Fatalf("nacked=%d saved=%d",q.nacked,sink.saved)}}
func TestProcessLogsAckFailureAfterSuccessfulPersist(t *testing.T){payload,_:=json.Marshal(testRecord());q:=&fakeQueue{ackErr:errors.New("lease expired")};sink:=&fakeSink{};c:=&Collector{Queue:q,Sink:sink,Config:Config{MaxAttempts:3},Logger:slog.New(slog.NewTextHandler(io.Discard,nil))};c.process(context.Background(),"worker",queue.Message{ID:"m1",Payload:payload,Attempts:1});if sink.saved!=1||q.acked!=1||q.nacked!=0{t.Fatalf("saved=%d ack=%d nack=%d",sink.saved,q.acked,q.nacked)}}
func TestNackLogsQueueFailure(t *testing.T){q:=&fakeQueue{nackErr:errors.New("queue down")};c:=&Collector{Queue:q,Config:Config{MaxAttempts:3},Logger:slog.New(slog.NewTextHandler(io.Discard,nil))};c.nack(context.Background(),"worker",queue.Message{ID:"m1",Attempts:1},errors.New("failure"));if q.nacked!=1{t.Fatalf("expected nack call")}}
func TestWorkerRetriesClaimErrorsAndStops(t *testing.T){ctx,cancel:=context.WithCancel(context.Background());q:=&fakeQueue{claimErr:errors.New("temporary db error")};c:=&Collector{Queue:q,Sink:&fakeSink{},ID:"test",Logger:slog.New(slog.NewTextHandler(io.Discard,nil)),Config:Config{Workers:1,BatchSize:1,PollInterval:time.Millisecond,LeaseDuration:time.Second,MaxAttempts:3}};done:=make(chan struct{});go func(){c.worker(ctx,0);close(done)}();time.Sleep(5*time.Millisecond);cancel();select{case<-done:case<-time.After(time.Second):t.Fatal("worker did not stop")};if q.claims==0{t.Fatal("expected queue claim attempts")}}
func TestRunRejectsMissingDependencies(t *testing.T){valid:=Config{Workers:1,BatchSize:1,PollInterval:time.Second,LeaseDuration:time.Second,MaxAttempts:1};cases:=[]*Collector{{Sink:&fakeSink{},ID:"x",Config:valid},{Queue:&fakeQueue{},ID:"x",Config:valid},{Queue:&fakeQueue{},Sink:&fakeSink{},Config:valid}};for i,c:=range cases{if err:=c.Run(context.Background());err==nil{t.Fatalf("case %d expected invalid config",i)}}}
func TestWorkerStopsBeforeProcessingAfterCancellation(t *testing.T){ctx,cancel:=context.WithCancel(context.Background());payload,_:=json.Marshal(testRecord());q:=&fakeQueue{messages:[]queue.Message{{ID:"m1",Payload:payload,Attempts:1}}};q.afterClaim=cancel;c:=&Collector{Queue:q,Sink:&fakeSink{},ID:"test",Logger:slog.New(slog.NewTextHandler(io.Discard,nil)),Config:Config{Workers:1,BatchSize:1,PollInterval:time.Millisecond,LeaseDuration:time.Second,MaxAttempts:3}};c.worker(ctx,0)}
